    24→import com.fasterxml.jackson.dataformat.smile.SmileGenerator;
    25→import com.google.inject.Binder;
    26→import com.google.inject.Key;
    27→import com.google.inject.Module;
    28→import com.google.inject.Provides;
    29→import org.apache.druid.guice.LazySingleton;
    30→import org.apache.druid.guice.annotations.Json;
    31→import org.apache.druid.guice.annotations.Smile;
    32→
    33→/**
    34→ */
    35→public class JacksonModule implements Module
    36→{
    37→  @Override
    38→  public void configure(Binder binder)
    39→  {
    40→    binder.bind(ObjectMapper.class).to(Key.get(ObjectMapper.class, Json.class));
    41→  }
    42→
    43→  @Provides @LazySingleton @Json
    44→  public ObjectMapper jsonMapper()
    45→  {
    46→    return new DefaultObjectMapper();
    47→  }
    48→
    49→  @Provides @LazySingleton @Smile
    50→  public ObjectMapper smileMapper()
    51→  {
    52→    final SmileFactory smileFactory = new SmileFactory();
    53→    smileFactory.configure(SmileGenerator.Feature.ENCODE_BINARY_AS_7BIT, false);
    54→    smileFactory.delegateToTextual(true);
    55→    final ObjectMapper retVal = new DefaultObjectMapper(smileFactory);
    56→    retVal.getFactory().setCodec(retVal);
    57→    return retVal;
    58→  }
    59→}
